#!/usr/bin/env python3
"""Sound hints for Latin American Spanish, generated by rules: "también" -> "tahm-BYEN".

Spanish spelling maps to sound almost one to one, so a hint can be computed instead of written by hand:
  1. group the letters into sound units (ch, ll, rr are one sound; the u in que/qui/gue/gui is silent),
  2. split the units into syllables around their vowels,
  3. find the stressed syllable (a written accent wins; otherwise the spelling rule decides),
  4. respell each syllable for an English reader, stressed syllable in capitals.
Latin American pronunciation: z and soft c sound like s, ll and y like y, and b and v are the same sound (spelled b).

Usage: python3 scripts/hints.py WORD...     print the hint for each word or phrase
       python3 scripts/hints.py --fill       fill empty hint cells in data/lexicon.csv
       python3 scripts/hints.py --check      list lexicon hints that differ from the rules (exit 1 if any)
"""
import argparse
import csv
from pathlib import Path
import sys

LEXICON = Path(__file__).resolve().parent.parent / 'data' / 'lexicon.csv'

ACCENTS = {'á': 'a', 'é': 'e', 'í': 'i', 'ó': 'o', 'ú': 'u', 'ü': 'u'}
VOWELS = set('aeiouáéíóúü') | {'Y'}  # Y: a y that sounds like the vowel i (y, muy, hay, estoy)
WEAK = {'i', 'u', 'ü', 'Y'}  # glide into a neighbouring vowel; accented í and ú do not
CLUSTERS = {'pl', 'pr', 'bl', 'br', 'fl', 'fr', 'cl', 'cr', 'gl', 'gr', 'dr', 'tr', 'kl', 'kr'}  # never split
ARTICLES = {'el', 'la', 'los', 'las', 'un', 'una', 'unos', 'unas'}
FRONT = set('eiéí')  # c and g go soft before these

# Vowel sounds, after accents are dropped. Closed syllables (ending in a consonant) adjust e and o below.
NUCLEUS = {
    'a': 'ah', 'e': 'eh', 'i': 'ee', 'o': 'oh', 'u': 'oo',
    'ia': 'yah', 'ie': 'yeh', 'io': 'yoh', 'iu': 'yoo',
    'ua': 'wah', 'ue': 'weh', 'uo': 'woh', 'ui': 'wee',
    'ai': 'eye', 'ei': 'ay', 'oi': 'oy', 'au': 'ow', 'eu': 'eh-oo', 'ou': 'ow',
    'uai': 'wye', 'uei': 'way', 'iai': 'yeye', 'iei': 'yay',
}
# Exceptions the rules can't know: x sounding like the Spanish j, and English loanwords.
OVERRIDES = {'méxico': 'MEH-hee-koh', 'mexicano': 'meh-hee-KAH-noh'}


def units(word):
    """Letters grouped into sound units."""
    out, i = [], 0
    while i < len(word):
        pair, after = word[i:i + 2], word[i + 2:i + 3]
        if pair in ('ch', 'll', 'rr'):
            out.append(pair)
            i += 2
        elif pair == 'qu' or (pair == 'gu' and after in FRONT):
            out.append(pair)  # silent u: que, aquí, guerra, seguir
            i += 2
        elif word[i] == 'x':
            # x sounds like ks and splits across syllables (éxito = EK-see-toh); before a soft c its s merges
            # into the c (excelente = ek-seh-LEN-teh)
            out += ['k'] if pair[1:] == 'c' and after in FRONT else ['k', 's']
            i += 1
        elif word[i] == 'y' and i == len(word) - 1:
            out.append('Y')  # word-final y is a vowel: y, muy, hay, hoy, estoy
            i += 1
        else:
            out.append(word[i])
            i += 1
    return out


def joins(a, b):
    """Two vowels side by side share a syllable (a diphthong) when either is a plain i, u or final y."""
    return a in WEAK or b in WEAK


def syllables(us):
    """Split sound units into syllables: one vowel group each, consonants shared out by the Spanish rules."""
    groups, i = [], 0
    while i < len(us):
        if us[i] in VOWELS:
            j = i + 1
            while j < len(us) and us[j] in VOWELS and joins(us[j - 1], us[j]):
                j += 1
            groups.append((i, j))
            i = j
        else:
            i += 1
    if not groups:
        return [us]
    cuts = []
    for (_, end), (start, _) in zip(groups, groups[1:]):
        between = us[end:start]
        n = len(between)
        cluster = n >= 2 and between[-2] + between[-1] in CLUSTERS
        coda = 0 if n <= 1 else n - 2 if cluster else n - 1  # one consonant, or a cluster, starts the next syllable
        cuts.append(end + coda)
    bounds = [0] + cuts + [len(us)]
    return [us[a:b] for a, b in zip(bounds, bounds[1:])]


def stress(word, sylls):
    """Index of the stressed syllable."""
    for k, syl in enumerate(sylls):
        if any(u in 'áéíóú' for u in syl):
            return k
    if len(sylls) == 1:
        return 0
    return len(sylls) - 2 if word[-1] in 'aeiouns' else len(sylls) - 1


def consonant(unit, nxt, prev, first):
    """Respelling of one consonant unit. nxt: the following unit; prev: the one before; first: starts the word."""
    if unit in ('b', 'v'):
        return 'b'
    if unit == 'c':
        return 's' if nxt in FRONT else 'k'
    if unit == 'g':
        return 'h' if nxt in FRONT else 'g'
    if unit == 'r':
        return 'rr' if first or prev in ('n', 'l', 's') else 'r'
    return {'h': '', 'j': 'h', 'll': 'y', 'ñ': 'ny', 'qu': 'k', 'gu': 'g', 'z': 's', 'rr': 'rr'}.get(unit, unit)


def nucleus(vowels, coda):
    plain = ''.join(ACCENTS.get(v, v) for v in vowels).replace('Y', 'i')
    sound = NUCLEUS.get(plain) or '-'.join(NUCLEUS[v] for v in plain)
    if coda and sound.endswith('eh') and not coda.startswith('r'):
        sound = sound[:-1]  # closed e: es, en, el, bien = byen
    if coda and sound.endswith('oh') and coda.startswith('r'):
        sound = sound[:-1]  # or: por, favor
    return sound


def respell_word(word, unstressed=False):
    word = word.lower()
    if word in OVERRIDES:
        return OVERRIDES[word].lower() if unstressed else OVERRIDES[word]
    us = units(word)
    sylls = syllables(us)
    hit = stress(word, sylls)
    out, index = [], 0
    for k, syl in enumerate(sylls):
        vowel_at = [i for i, u in enumerate(syl) if u in VOWELS]
        if not vowel_at:
            out.append(''.join(syl))
            index += len(syl)
            continue
        a, b = vowel_at[0], vowel_at[-1] + 1
        onset, coda = [], []
        for i, u in enumerate(syl):
            if i < a or i >= b:
                pos = index + i
                text = consonant(u, us[pos + 1] if pos + 1 < len(us) else '', us[pos - 1] if pos else '', pos == 0)
                (onset if i < a else coda).append(text)
        sound = nucleus(syl[a:b], ''.join(coda))
        if ''.join(onset) and sound.startswith('eye'):
            sound = sound[1:]  # bailar = bye-LAHR, not beye-LAHR
        part = ''.join(onset) + sound + ''.join(coda)
        out.append(part.upper() if k == hit and len(sylls) > 1 and not unstressed else part)
        index += len(syl)
    return '-'.join(out)


def respell_adverb(word, unstressed=False):
    """-mente adverbs keep the adjective's stress and add their own: rápidamente = RRAH-pee-dah-MEN-teh."""
    if len(word) > 5 and word.endswith('mente') and not unstressed:
        return respell_word(word[:-5]) + '-MEN-teh'
    return respell_word(word, unstressed)


def respell(phrase):
    """Hint for a word or phrase; a leading article stays unstressed ("el problema" = "el proh-BLEH-mah")."""
    words = phrase.strip(' ¿?¡!.,').split()
    return ' '.join(respell_adverb(w.lower(), unstressed=(i == 0 and len(words) > 1 and w.lower() in ARTICLES))
                    for i, w in enumerate(words))


def rows():
    with open(LEXICON, encoding='utf-8', newline='') as file:
        return list(csv.DictReader(file))


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument('words', nargs='*')
    parser.add_argument('--fill', action='store_true')
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args(argv)
    if args.fill:
        table = rows()
        filled = 0
        for row in table:
            if not (row.get('hint') or '').strip():
                row['hint'] = respell(row['es'])
                filled += 1
        with open(LEXICON, 'w', encoding='utf-8', newline='') as file:
            writer = csv.DictWriter(file, fieldnames=['es', 'en', 'hint'], lineterminator='\n')
            writer.writeheader()
            writer.writerows({k: row[k] for k in ('es', 'en', 'hint')} for row in table)
        print(f'filled {filled} hints')
    elif args.check:
        differ = [(row['es'], row['hint'], respell(row['es'])) for row in rows() if row['hint'] != respell(row['es'])]
        for es, have, rule in differ:
            print(f'{es}: lexicon "{have}", rules "{rule}"')
        sys.exit(1 if differ else 0)
    for word in args.words:
        print(f'{word} = {respell(word)}')


if __name__ == '__main__':
    main()
